-- Troll origins. DRAFT for the user's approval. Year 1: the Darkspear sailed with Thrall,
-- were driven off the Echo Isles by Zalazane, and settled at Sen'jin.
local P = RPGDialogueAPI:Pack("rpgd.world")

P:Origin {
  id = "troll", race = "Troll",
  origins = {
    { id = "troll_echo_isles", name = "Darkspear from the Echo Isles",
      blurb = "The Echo Isles are home, mon, and Zalazane is sitting on them with his hexed slaves. Every Darkspear knows we're going back one day.",
      nudge = { trait = { brave = 1 }, align = { order = -1 } }, home = "senjin" },
    { id = "troll_sailed_with_thrall", name = "Sailed with Thrall from the south seas",
      blurb = "The sea witch and the murlocs would have had us all if the Warchief hadn't come. Vol'jin's father swore our debt to the Horde, and I was there to hear it.",
      nudge = { trait = { generous = 1 }, align = { honor = 2 } }, home = "senjin" },
    { id = "troll_witch_doctor_apprentice", name = "Apprentice to a Darkspear witch doctor",
      blurb = "I ground roots and boiled things that still moved for an old witch doctor at Sen'jin. He taught me that every loa wants something, and to know what before you ask.",
      nudge = { trait = { curious = 1 }, align = { order = -1 } }, home = "senjin" },
    { id = "troll_headhunter", name = "Headhunter of the Darkspear", class = "HUNTER",
      blurb = "My father took heads in Stranglethorn and his father before him. I hunt for the Horde now, and I keep the habit of watching the treeline.",
      nudge = { trait = { stern = 1 }, align = { honor = -1 } } },
    { id = "troll_loa_speaker", name = "Speaker for the loa", class = "PRIEST",
      blurb = "The loa speak and I listen, and sometimes I tell people what they said. Most of the time I keep it to myself, because the loa have a cruel sense of humor.",
      nudge = { trait = { pious = 1 }, align = { light = 1, order = -1 } } },
    { id = "troll_other_voice", name = "Listener to a voice that isn't a loa", class = "WARLOCK",
      blurb = "One night a voice spoke to me that didn't want an offering, only a bargain. The witch doctors won't speak to me now, and I didn't stop listening.",
      nudge = { trait = { curious = 1 }, align = { light = -2 } } },
    { id = "troll_senjin_spear", name = "Spear of the Sen'jin watch", class = "WARRIOR",
      blurb = "Kul Tiras is camped on the coast north of us and the Kolkar raid from the south, so Sen'jin needs spears more than prayers. I've held the village gate more nights than I can count, mon.",
      nudge = { trait = { brave = 1 }, align = { order = 1, honor = 1 } }, home = "senjin" },
    { id = "troll_revantusk_envoy", name = "Revantusk warrior from the Hinterlands", class = "WARRIOR",
      blurb = "My tribe holds the Hinterlands coast against the Witherbark and every old Amani grudge. The Revantusk sent me to see what the Horde is worth as an ally, and so far it's been better company than the Amani ever were.",
      nudge = { trait = { skeptical = 1 }, align = { honor = 1, order = -1 } }, home = "revantusk" },
    { id = "troll_raptor_rider", name = "Raptor rider of Sen'jin", class = "HUNTER",
      blurb = "Darkspear have ridden raptors longer than anyone can remember, mon. I raised mine from an egg in the pens at Sen'jin, and she'll bite anyone but me.",
      nudge = { trait = { generous = 1 }, align = { honor = 1 } }, home = "senjin" },
    { id = "troll_gurubashi_runaway", name = "Runaway from the Gurubashi", class = "ROGUE",
      blurb = "I was born among the Gurubashi in Stranglethorn, where the priests of Hakkar are waking something they shouldn't. I slipped away with a few knives and fewer friends, and the Darkspear took me in without asking too many questions.",
      nudge = { trait = { cautious = 1 }, align = { light = 1, order = -1 } }, home = "gromgol" },
    { id = "troll_echo_isles_spy", name = "Night spy on the Echo Isles", class = "ROGUE",
      blurb = "I paddle out to the Echo Isles at night to count Zalazane's hexed slaves, and I come back before he can count me among them. Somebody has to know how many there are, mon, for the day we take the isles back.",
      nudge = { trait = { brave = 1 }, align = { order = 1, honor = 1 } }, home = "senjin" },
    { id = "troll_bwonsamdi_singer", name = "Singer for Bwonsamdi", class = "PRIEST",
      blurb = "Bwonsamdi watches over the dead, and somebody has to keep him in good humor. I sing for the Darkspear who fell on the Echo Isles, so the loa of death doesn't forget their names.",
      nudge = { trait = { stern = 1 }, align = { light = -1, order = 1 } }, home = "senjin" },
    { id = "troll_sea_spirit_caller", name = "Caller of the sea spirits", class = "SHAMAN",
      blurb = "The Darkspear lived by the sea long before we met an orc, and the water spirits remember us. I learned to call them from the old women on the shore at Sen'jin, not from any orc far seer.",
      nudge = { trait = { pious = 1 }, align = { order = -1, honor = 1 } }, home = "senjin" },
    { id = "troll_orgrimmar_shaman", name = "Taught by the Warchief's shamans", class = "SHAMAN",
      blurb = "The orc shamans in Orgrimmar taught me to speak with earth and fire the way their clans do. My grandmother says I've forgotten the loa, but I think the spirits and the loa can share one troll.",
      nudge = { trait = { curious = 1 }, align = { light = 1, order = 1 } }, home = "orgrimmar" },
    { id = "troll_zandalari_scrolls", name = "Reader of Zandalari scrolls", class = "MAGE",
      blurb = "My uncle traded with the Zandalari who sail to Stranglethorn, and he came home with scrolls older than the Horde. I learned my first spells from those, long before I ever heard the word Dalaran.",
      nudge = { trait = { curious = 1 }, align = { honor = 1 } } },
    { id = "troll_valley_of_spirits_mage", name = "Student in the Valley of Spirits", class = "MAGE",
      blurb = "Old troll mojo and human arcane come from the same place if you ask me, mon, but nobody does. I study in the Valley of Spirits, where the orcs walk past quickly and the trolls nod like they understand.",
      nudge = { trait = { witty = 1 }, align = { order = 1, light = -1 } }, home = "orgrimmar" },
    { id = "troll_hex_breaker", name = "Learned dark magic to fight Zalazane", class = "WARLOCK",
      blurb = "Zalazane took the Echo Isles with dark hexes, and the Darkspear need someone who understands that kind of power from the inside. I learned it from the warlocks in the Cleft of Shadow, and Vol'jin pretends not to know.",
      nudge = { trait = { cautious = 1 }, align = { light = -1, order = 1 } }, home = "orgrimmar" },
    { id = "troll_coast_fisher", name = "Fisher of the Durotar coast",
      blurb = "I pulled nets off the Durotar coast long before anyone handed me a weapon. The sea feeds Sen'jin when the land won't, and I've seen enough murlocs and Kul Tiran sails to know it isn't always kind.",
      nudge = { trait = { generous = 1 }, align = { order = 1 } }, home = "senjin" },
    { id = "other", name = "Other" },
  },
}
